function createPixelPart(id: string, name: string, rows: string[], offsetY = 0): AvatarPartItem {
  return {
    id,
    name,
    patches: rows.flatMap((row, y) => [...row].flatMap((token, x) =>
      token === '.' ? [] : [[y + offsetY, x, token] as PatchCoord]
    )),
  };
}

